// Deeper interaction audit for mail: open a message, open compose, open settings,
// open contact panel, check attachment lightbox. Dark + light. Temporary.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = process.env.NX_EMAIL || "customer@nxeon.local";
const PASS = process.env.NX_PASS || "wGPZqhCbsLdz";
const out = process.argv[2] || "/tmp/audit-c2";
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();

await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
await page.waitForTimeout(1000);
const gotIt = page.getByRole("button", { name: /got it/i });
if (await gotIt.isVisible().catch(() => false)) await gotIt.click();
await page.fill('input[type="email"], input[name="email"]', EMAIL);
await page.fill('input[type="password"], input[name="password"]', PASS);
await Promise.all([
  page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 45000 }).catch(() => {}),
  page.click("button.btn-primary"),
]);
await page.waitForTimeout(1500);

async function shoot(mode, name) {
  await page.waitForTimeout(600);
  await page.screenshot({ path: join(out, `${mode}-${name}.png`) });
  console.log(`${mode}-${name}`);
}

async function run(mode) {
  await page.goto(`${BASE}/dashboard/mail`, { waitUntil: "networkidle", timeout: 60000 }).catch(() => {});
  if (mode === "light") {
    await page.evaluate(() => {
      localStorage.setItem("nx-theme", "light");
      document.documentElement.setAttribute("data-theme", "light");
    });
    await page.reload({ waitUntil: "networkidle" }).catch(() => {});
  }
  await page.waitForTimeout(1000);
  // dismiss cookie banner if present again (per-domain state may persist though)
  const gi = page.getByRole("button", { name: /got it/i });
  if (await gi.isVisible().catch(() => false)) await gi.click();

  // Open first message with attachment (Amelia Frost - has paperclip)
  const msg = page.getByText("Amelia Frost").first();
  if (await msg.isVisible().catch(() => false)) {
    await msg.click();
    await shoot(mode, "reading-pane");
    // try to expand contact panel
    const contactToggle = page.locator('button:has-text("Contact")').first();
  }

  // Open Compose
  const composeBtn = page.getByRole("button", { name: /compose/i }).first();
  if (await composeBtn.isVisible().catch(() => false)) {
    await composeBtn.click();
    await shoot(mode, "compose");
    // close compose
    const closeBtns = page.locator('button[aria-label="Close" i], button:has-text("×")');
  }

  await page.keyboard.press("Escape").catch(() => {});
  await page.waitForTimeout(300);

  // Mail settings
  const settingsLink = page.getByText("Mail settings", { exact: false }).first();
  if (await settingsLink.isVisible().catch(() => false)) {
    await settingsLink.click();
    await shoot(mode, "settings");
  }
}

await run("dark");
await run("light");

await browser.close();

