import { useTerminalDock } from "@/components/customer/terminal/TerminalDock";
import {
  QUICKSTART,
  SETUP_FLOWS,
  CATEGORIES,
  PROMPTS,
  GUIDES,
  type TerminalLine,
  type PromptTemplate,
} from "@/lib/ai-build";

/* -------------------------------------------------------------------------- */
/* Small building blocks                                                       */
/* -------------------------------------------------------------------------- */

function ClaudeGlyph({ className = "" }: { className?: string }) {
  // Owner-provided Claude brand asset — the single source of truth for the mark.
  return <Image src="/logos/claude.png" alt="Claude" width={28} height={28} className={className} aria-hidden />;
}

function CopyButton({ text, label = "Copy", className = "" }: { text: string; label?: string; className?: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(text);
          setCopied(true);
          setTimeout(() => setCopied(false), 1600);
        } catch {
          /* clipboard unavailable */
        }
      }}
      className={`inline-flex items-center gap-1.5 rounded-lg border px-3 py-1.5 text-xs font-semibold transition ${
        copied
          ? "border-emerald-400/40 bg-emerald-400/10 text-emerald-300"
          : "border-white/10 bg-white/5 text-slate-200 hover:bg-white/10"
      } ${className}`}
    >
      {copied ? (
        <>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <path d="M20 6 9 17l-5-5" />
          </svg>
          Copied
        </>
      ) : (
        <>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <rect x="9" y="9" width="13" height="13" rx="2" />
            <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
          </svg>
          {label}
        </>
      )}
    </button>
  );
}

const LINE_STYLE: Record<TerminalLine["kind"], string> = {
  cmd: "text-slate-100",
  out: "text-slate-400",
  claude: "text-[#e8a889]",
  comment: "text-slate-500",
  input: "text-amber-300",
  ok: "text-emerald-400",
};

function Terminal({ title = "bash", lines }: { title?: string; lines: TerminalLine[] }) {
  return (
    <div className="overflow-hidden rounded-xl border border-white/10 bg-[#0a0e1a] shadow-lg shadow-black/30">
      <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.03] px-3.5 py-2">
        <span className="h-2.5 w-2.5 rounded-full bg-[#ff5f57]" />
        <span className="h-2.5 w-2.5 rounded-full bg-[#febc2e]" />
        <span className="h-2.5 w-2.5 rounded-full bg-[#28c840]" />
        <span className="ml-2 text-[11px] font-medium text-slate-500">{title}</span>
      </div>
      <pre className="overflow-x-auto px-4 py-3 font-mono text-[12.5px] leading-relaxed">
        {lines.map((l, i) => (
          <div key={i} className={LINE_STYLE[l.kind]}>
            {l.kind === "cmd" && <span className="select-none text-emerald-400">$ </span>}
            {l.kind === "claude" && <span className="select-none text-[#D97757]">✳ </span>}
            {l.text || " "}
          </div>
        ))}
      </pre>
    </div>
  );
}

function Section({ id, eyebrow, title, sub, children, hidden }: { id?: string; eyebrow?: string; title: string; sub?: string; children: React.ReactNode; hidden?: boolean }) {
  return (
    /* `hidden` rather than unmounting: the setup flow, the prompt filters and a
       half-open guide keep their state when the reader flips to another tab and
       back, which is what they expect from a sub-nav. */
    <section id={id} hidden={hidden} className="scroll-mt-24">
      <div className="mb-4">
        {eyebrow && <p className="text-[11px] font-semibold uppercase tracking-[0.2em] text-brand-300/80">{eyebrow}</p>}
        <h2 className="mt-1 text-xl font-bold tracking-tight text-white">{title}</h2>
        {sub && <p className="mt-1 max-w-2xl text-sm text-slate-400">{sub}</p>}
      </div>
      {children}

