"use client";

import { useEffect, useRef } from "react";
import { isLightTheme, auroraComposite, auroraStrandGradient } from "./auroraTheme";

/* Mail's own light field — the same canvas technique every other account page's
 * aurora uses (sine-path ribbon strokes, additive blend, a blurred halo plus a
 * hard-edged core), with its own ribbon family so the page reads as itself:
 * cyan into blue into violet, the mail mark's own hues, cooler and calmer than
 * Team's blue-magenta. Mailboxes was the last account page still opening on a
 * flat header while Billing, Support, Activity, What's New and Team each had
 * one of these.
 */
type Ribbon = {
  y: number; amp: number; freq: number; speed: number; phase: number;
  width: number; hue: [number, number]; alpha: number;
};

const RIBBONS: Ribbon[] = [
  { y: 0.18, amp: 0.13, freq: 0.80, speed: 0.12, phase: 0.6, width: 62, hue: [186, 214], alpha: 0.20 },
  { y: 0.30, amp: 0.16, freq: 0.70, speed: -0.10, phase: 2.2, width: 74, hue: [214, 258], alpha: 0.17 },
  { y: 0.13, amp: 0.08, freq: 1.4, speed: 0.19, phase: 3.9, width: 34, hue: [258, 282], alpha: 0.15 },
  { y: 0.25, amp: 0.05, freq: 2.1, speed: 0.24, phase: 5.3, width: 15, hue: [190, 222], alpha: 0.24 },
];

export function MailAurora() {
  const ref = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const cv = ref.current;
    if (!cv) return;
    const ctx = cv.getContext("2d", { alpha: true });
    if (!ctx) return;

    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    let raf = 0, t = 0, running = true;

    const fit = () => {
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      const r = cv.getBoundingClientRect();
      cv.width = Math.max(1, Math.round(r.width * dpr));
      cv.height = Math.max(1, Math.round(r.height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const strand = (r: Ribbon, w: number, h: number, time: number, isLight: boolean) => {
      ctx.strokeStyle = auroraStrandGradient(ctx, r, w, isLight);
      ctx.lineWidth = r.width;
      ctx.lineCap = "round";
      ctx.beginPath();
      for (let x = 0; x <= w; x += 8) {
        const u = x / w;
        const y = h * (r.y
          + r.amp * Math.sin(u * Math.PI * 2 * r.freq + time * r.speed + r.phase)
          + r.amp * 0.4 * Math.sin(u * Math.PI * 2 * (r.freq * 1.7) - time * r.speed * 0.6));
        x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.stroke();
    };

    const paint = (time: number) => {
      const w = cv.clientWidth, h = cv.clientHeight;
      const isLight = isLightTheme();
      ctx.clearRect(0, 0, w, h);
      ctx.globalCompositeOperation = auroraComposite(isLight);
      ctx.filter = "blur(30px)";
      for (const r of RIBBONS) strand(r, w, h, time, isLight);
      ctx.filter = "blur(4px)";
      for (const r of RIBBONS) strand({ ...r, width: r.width * 0.22, alpha: r.alpha * 1.5 }, w, h, time, isLight);
      ctx.filter = "none";
      for (const r of RIBBONS) strand({ ...r, width: Math.max(1.2, r.width * 0.045), alpha: Math.min(1, r.alpha * 1.9) }, w, h, time, isLight);
      ctx.globalCompositeOperation = "source-over";
    };

    const draw = () => {
      if (!running) return;
      paint(t);
      t += 0.013;
      raf = requestAnimationFrame(draw);
    };

    fit();
    if (reduced) {
      // One still frame at a pleasing phase, rather than nothing at all.
      paint(2.4);
    } else {
      raf = requestAnimationFrame(draw);
    }

    const onResize = () => { fit(); if (reduced) paint(2.4); };
    const onVis = () => {
      if (document.hidden) { running = false; cancelAnimationFrame(raf); }
      else if (!reduced && !running) { running = true; raf = requestAnimationFrame(draw); }
    };
    window.addEventListener("resize", onResize);
    document.addEventListener("visibilitychange", onVis);
    return () => {
      running = false;
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", onResize);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, []);

  return (
    <div aria-hidden
         className="pointer-events-none fixed inset-x-0 top-0 z-0 h-[420px] overflow-hidden lg:left-[76px] xl:left-[248px]">
      <canvas ref={ref} className="h-full w-full opacity-80" />
      <span className="nx-aurora-dot" style={{ left: "18%", top: "18%", animationDelay: "0s" }} />
      <span className="nx-aurora-dot" style={{ left: "44%", top: "10%", animationDelay: "1.9s" }} />
      <span className="nx-aurora-dot" style={{ left: "67%", top: "22%", animationDelay: "3.1s" }} />
      <span className="nx-aurora-dot" style={{ left: "86%", top: "13%", animationDelay: "1.1s" }} />
      <span className="absolute inset-0"
            style={{ background: "linear-gradient(180deg, color-mix(in srgb, var(--color-bg) 6%, transparent) 0%, color-mix(in srgb, var(--color-bg) 32%, transparent) 46%, color-mix(in srgb, var(--color-bg) 78%, transparent) 76%, var(--color-bg) 98%)" }} />
    </div>
  );
}

